const initial=[['1042','Waterlogging','Hospital Road, Indiranagar','HIGH','hospital',20,3,'Pending',12.9781,77.6408],['1043','Pothole','12th Main, School Zone','HIGH','school',14,5,'Assigned',12.9731,77.6361],['1044','Garbage','Market Street, Domlur','MEDIUM','market',8,4,'In Progress',12.9633,77.6386],['1045','Pothole','5th Cross, HAL 2nd Stage','MEDIUM','residential',3,2,'Pending',12.9706,77.6504],['1046','Waterlogging','Old Airport Road','HIGH','main road',9,2,'Pending',12.9581,77.6515],['1047','Garbage','CMH Road, Indiranagar','LOW','residential',2,1,'Resolved',12.983,77.6375],['1048','Pothole','100 Feet Road','MEDIUM','main road',6,8,'In Progress',12.972,77.6415],['1049','Garbage','Jeevan Bima Nagar','MEDIUM','residential',4,12,'Resolved',12.9737,77.6582]];
function priority(i){let severity={LOW:15,MEDIUM:30,HIGH:45}[i.severity]||15,importance={hospital:25,school:20,'main road':15,market:10,residential:0}[i.importance]||0,reports=Math.min(20,(i.reports||1)*1.2),hours=Math.max(0,(Date.now()-new Date(i.created_at))/36e5),age=Math.min(10,hours/3),score=Math.round(severity+importance+reports+age);return{level:score>=80?'CRITICAL':score>=60?'HIGH':score>=35?'MEDIUM':'LOW',score,reasons:[`${i.severity.toLowerCase()} severity (${severity} points)`,`${i.importance||'residential'} access (${importance} points)`,`${i.reports||1} citizen reports (${Math.round(reports)} points)`,`Unresolved for ${hours.toFixed(1)} hours (${Math.round(age)} points)`]};}
let incidents=initial.map(([id,issue_type,address,severity,importance,reports,hours,status,latitude,longitude])=>({id:'CIV-'+id,issue_type,address,severity,importance,reports,status,latitude,longitude,department:departments[issue_type],confidence:.94,created_at:new Date(Date.now()-hours*36e5).toISOString(),updated_at:now(),image_url:null,worker_id:status==='Assigned'||status==='In Progress'?'demo-worker':null,history:[{status:'Reported',created_at:new Date(Date.now()-hours*36e5).toISOString()},{status,created_at:now()}]}));
let state={page:location.hash.slice(1)||location.pathname.replace(/^\/+|\/+$/g,'')||'home',role:null,user:null,filter:{},selected:null,report:null,config:window.CIVICEYE_CONFIG||{},live:false}, maps=[],stream=null,scanTimer=null;
const savedConfig=localStorage.getItem('civiceye-public-settings');if(savedConfig){try{state.config=JSON.parse(savedConfig)}catch{}}
let client=null;if(state.config.supabaseUrl&&state.config.supabaseAnonKey&&window.supabase){client=window.supabase.createClient(state.config.supabaseUrl,state.config.supabaseAnonKey);state.live=true;incidents=[];}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
const badge=p=>`<span class="badge ${p.toLowerCase()}">${p}</span>`;
const ago=t=>{const h=(Date.now()-new Date(t))/36e5;return h<1?Math.max(1,Math.round(h*60))+'m ago':h<24?Math.round(h)+'h ago':Math.floor(h/24)+'d ago'};
function legacyNavigate(page){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}clearInterval(scanTimer);state.page=page;state.filter={};location.hash=page;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==state.page)navigate(p)});
function header(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${state.role==='authority'?'Municipal command center':state.role==='worker'?'Field operations':'Citizen portal'}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function shell(content){const links=state.role==='authority'?[['live-scan','eye','Live Scan'],['dashboard','grid','Overview'],['incidents','list','All incidents'],['map','map','Incident map'],['analytics','chart','Analytics'],['workers','users','Field teams'],['drivescan','camera','DriveScan'],['assistant','spark','Ask CivicEye']]:state.role==='worker'?[['tasks','briefcase','Assigned tasks'],['completed','check','Completed tasks']]:[['citizen','grid','Overview'],['live-scan','eye','Live Scan'],['report','camera','Report an issue'],['reports','list','My reports'],['nearby','map','Nearby issues'],['resolved','check','Resolved issues']];return `<aside class="sidebar" id="sidebar"><a class="logo" href="#home"><img src="favicon.svg" alt="">CivicEye <em>AI</em></a><div class="nav-label">WORKSPACE</div>${links.map(([page,ico,label])=>`<button class="nav-item ${state.page===page?'active':''}" data-page="${page}">${icon(ico)}${label}${page==='incidents'?`<small>${incidents.length}</small>`:''}</button>`).join('')}<div class="sidebar-bottom"><div class="side-note"><b>${icon('eye')} Every issue. A clear path.</b>From the first report to verified resolution.</div><button class="nav-item" data-page="settings">${icon('settings')}Connections</button><button class="nav-item" id="signout">${icon('logout')}Sign out</button></div></aside><div class="shell"><header class="topbar"><button class="btn ghost mobile-menu" id="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace &nbsp; / &nbsp; <b>${esc(links.find(x=>x[0]===state.page)?.[2]||'Incident details')}</b></div><div class="top-right"><span class="badge ${state.live?'resolved':'demo'}">${state.live?'Live AI mode':'Demo mode'}</span><div class="user"><div class="avatar">${state.role==='authority'?'MA':state.role==='worker'?'FW':'CI'}</div><div>${esc(state.user?.name||({authority:'Municipal Authority',citizen:'Demo Citizen',worker:'Field Worker'}[state.role]))}<small>${state.role==='authority'?'City operations':state.role==='worker'?'Road Team A':'Community member'}</small></div></div></div></header><main class="main">${content}<div class="footer"><span>CivicEye AI · See. Detect. Prioritize. Resolve.</span><span>${state.live?'Connected to Supabase':'Local prototype · records saved on this device'}</span></div></main></div>`}
function stats(){let open=incidents.filter(i=>!['Resolved','Rejected'].includes(i.status)),resolved=incidents.filter(i=>i.status==='Resolved');let durations=resolved.map(i=>(new Date(i.updated_at)-new Date(i.created_at))/36e5);return `<div class="stats">${[[incidents.length,'Total incidents','list','Across all departments'],[open.filter(i=>priority(i).level==='CRITICAL').length,'Critical incidents','alert','Needs immediate attention'],[open.filter(i=>i.status==='Pending').length,'Pending','clock','Awaiting assignment'],[open.filter(i=>['Assigned','Accepted','En Route','On Site','In Progress'].includes(i.status)).length,'In progress','briefcase','Field teams at work'],[resolved.filter(i=>new Date(i.updated_at).toDateString()===new Date().toDateString()).length,'Resolved today','check','Repairs completed'],[durations.length?(durations.reduce((a,b)=>a+b,0)/durations.length).toFixed(1)+'h':'—','Avg. resolution','clock','From report to resolution']].map(([v,l,ic,f])=>`<div class="stat"><div class="stat-top">${l}${icon(ic)}</div><div class="stat-value" ${l==='Critical incidents'?'style="color:var(--red)"':''}>${v}</div><div class="stat-foot">${f}</div></div>`).join('')}</div>`}
function sorted(){return incidents.filter(i=>!['Resolved','Rejected'].includes(i.status)).sort((a,b)=>priority(b).score-priority(a).score)}
function queue(limit=4){return sorted().slice(0,limit).map(i=>`<div class="queue-row" data-incident="${esc(i.id)}"><div class="issue-icon ${i.issue_type}">${typeIcon(i.issue_type)}</div><div class="row-body"><div class="row-title">${i.issue_type}${badge(priority(i).level)}</div><p>${esc(i.address)}</p><div class="row-meta"><span>${i.reports} reports · ${ago(i.created_at)}</span><span>${esc(i.id)}</span></div></div></div>`).join('')||'<div class="empty">No incidents waiting for action.</div>'}
function mapPanel(id='incident-map'){return `<section class="panel"><div class="panel-head"><h2>Incident map <span class="count-pill">${incidents.length} incidents</span></h2><span class="live">${state.live?'Connected':'Sample data'}</span></div><div class="map" id="${id}"></div><div class="map-legend">${['Critical','High','Medium','Resolved'].map(s=>`<span><i class="dot ${s.toLowerCase()}"></i>${s}</span>`).join('')}</div></section>`}
function dashboard(){return header('A clearer view. A better city.','Monitor your city, prioritize what matters, and keep repairs moving.',`<span class="date">${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</span><button class="btn" id="refresh">${icon('check')}Refresh</button>`)+stats()+`<div class="grid-main">${mapPanel()}<section class="panel"><div class="panel-head"><div><h2>AI priority queue</h2><p>Highest-impact issues first</p></div>${icon('spark')}</div>${queue()}<button class="queue-foot full button-link" data-page="incidents">View all incidents</button></section></div>`+incidentTable(true)+`<div class="overview-bottom">${chartPanel('Issues by type','issue_type')}${chartPanel('Department workload','department',true)}</div>`}
function filtered(){return incidents.filter(i=>{const f=state.filter;return (!f.search||[i.id,i.address,i.issue_type].join(' ').toLowerCase().includes(f.search.toLowerCase()))&&(!f.type||i.issue_type===f.type)&&(!f.priority||priority(i).level===f.priority)&&(!f.status||i.status===f.status)&&(!f.department||i.department===f.department)&&(!f.area||i.address.toLowerCase().includes(f.area.toLowerCase()))&&(!f.date||new Date(i.created_at).toISOString().slice(0,10)===f.date)}).sort((a,b)=>priority(b).score-priority(a).score)}
function incidentTable(short=false,list=null){const rows=(list||filtered()).slice(0,short?5:1000);return `<section class="panel"><div class="panel-head"><h2>${short?'Recent incidents':'Incident directory'}<span class="count-pill">${rows.length}</span></h2><span class="subtext">${state.live?'Synced data':'Demo records'}</span></div>${list?'':`<div class="filters"><div class="search">${icon('search')}<input id="search" placeholder="Search incident or location…" aria-label="Search incidents" value="${esc(state.filter.search||'')}"></div>${filterSelect('type','All issue types',['Pothole','Garbage','Waterlogging'])}${filterSelect('priority','All priorities',['CRITICAL','HIGH','MEDIUM','LOW'])}${filterSelect('status','All statuses',['Pending','Assigned','Accepted','En Route','On Site','In Progress','Review Required','Resolved','Rejected'])}${short?'':filterSelect('department','All departments',Object.values(departments))+`<input id="area-filter" placeholder="Filter by area" aria-label="Filter by area" style="width:160px" value="${esc(state.filter.area||'')}"><input id="date-filter" type="date" aria-label="Filter by reporting date" style="width:160px" value="${esc(state.filter.date||'')}">`}</div>`}<div class="table-wrap"><table><thead><tr><th>INCIDENT ID</th><th>ISSUE TYPE</th><th>LOCATION</th><th>PRIORITY</th><th>STATUS</th><th>REPORTS</th><th>REPORTED</th></tr></thead><tbody>${rows.map(i=>`<tr data-incident="${esc(i.id)}" tabindex="0" aria-label="View ${esc(i.id)}"><td style="font-weight:600">${esc(i.id)}</td><td><div class="table-issue"><div class="issue-icon ${i.issue_type}">${typeIcon(i.issue_type)}</div>${i.issue_type}</div></td><td>${esc(i.address)}<div class="subtext">${esc(i.department)}</div></td><td>${badge(priority(i).level)}</td><td><span class="badge ${i.status==='Resolved'?'resolved':'status'}">${esc(i.status)}</span></td><td>${i.reports}</td><td class="subtext">${ago(i.created_at)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No incidents match this view.</div>'}</div><div class="table-foot">Showing ${rows.length} ${rows.length===1?'incident':'incidents'} · Priority considers severity, location, reports, and age</div></section>`}
function filterSelect(key,label,opts){return `<select data-filter="${key}" aria-label="${label}"><option value="">${label}</option>${opts.map(v=>`<option ${state.filter[key]===v?'selected':''}>${v}</option>`).join('')}</select>`}
function chartPanel(title,key,openOnly=false){const list=openOnly?incidents.filter(i=>!['Resolved','Rejected'].includes(i.status)):incidents;const counts={};list.forEach(i=>{const k=key==='priority'?priority(i).level:i[key];counts[k]=(counts[k]||0)+1});const max=Math.max(1,...Object.values(counts));return `<section class="panel"><div class="panel-head"><h2>${title}</h2><span class="subtext">${list.length} incidents</span></div><div class="chart">${Object.entries(counts).map(([k,n])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><div class="bar" style="width:${n/max*100}%"></div></div><b>${n}</b></div>`).join('')||'<p>No data yet.</p>'}</div></section>`}
function home(){return `<div class="landing"><nav class="landing-nav"><a class="logo" href="#home"><img src="favicon.svg" alt="">CivicEye <em>AI</em></a><div class="actions"><button class="btn ghost" id="authority-login">Authority login</button><button class="btn navy" id="citizen-login">Report an issue</button></div></nav><div class="hero"><div><div class="eyebrow">Civic intelligence, made actionable</div><h1>See. Detect.<br>Prioritize.<br><span>Resolve.</span></h1><p>AI-powered civic infrastructure monitoring from detection to verified resolution.</p><div class="actions"><button class="btn primary" id="hero-report">${icon('camera')}Report an issue</button><button class="btn" id="explore">Explore command center</button></div><div class="hero-proof">One camera. Three issue types. A complete path to repair.</div></div><div class="hero-panel"><div class="panel-head"><h2>Municipal command center</h2><span class="badge demo">Demo preview</span></div><div id="hero-map" class="map"></div>${queue(3)}</div></div><section class="how"><div class="eyebrow">How it works</div><h2>From a photo to a fix.</h2><p>A connected workflow. Accountability at every step.</p><div class="steps">${[['camera','Capture','Photograph a visible issue.'],['eye','Detect','Analyze visual evidence.'],['chart','Prioritize','Understand what matters most.'],['users','Assign','Route to the right team.'],['briefcase','Resolve','Track the repair in the field.'],['check','Verify','Review the after-repair image.']].map(([i,t,p])=>`<div class="step">${icon(i)}<b>${t}</b><p>${p}</p></div>`).join('')}</div></section><section class="classes"><div><div class="eyebrow">Initial detection classes</div><h2>Small signals.<br>Real city impact.</h2></div>${[['Pothole','Road damage and visible depressions.'],['Garbage','Visible waste accumulation.'],['Waterlogging','Standing water and water-filled potholes.']].map(([t,p])=>`<div class="class-card"><div class="issue-icon ${t}">${typeIcon(t)}</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</section><div class="landing-nav"><span class="subtext">CivicEye AI · Built for better city operations</span><button class="button-link" id="settings-home">Connect live services</button></div></div>`}
function legacyLogin(){return `<div class="login-layout"><aside class="login-aside"><a class="logo" href="#home"><img src="favicon.svg" alt="">CivicEye <em>AI</em></a><div><div class="eyebrow" style="color:#6fd7c1">A connected civic workflow</div><h1>A better city<br>starts with<br>a clearer view.</h1><p>See. Detect. Prioritize. Resolve.</p></div><p>Citizen reports. Municipal action. Verified repairs.</p></aside><section class="login-form"><h1>Welcome to CivicEye</h1><p>Choose your workspace to continue.</p><div class="role-choices">${[['citizen','users','Citizen'],['authority','grid','Authority'],['worker','briefcase','Field worker']].map(([v,i,l])=>`<button class="role-choice ${state.loginRole===v?'active':''}" data-role="${v}">${icon(i)}${l}</button>`).join('')}</div>${state.live?`<form id="login-form"><label class="field">Email<input name="email" type="email" autocomplete="email" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><button class="btn primary full" type="submit">Sign in</button></form><p class="subtext">Roles are assigned by your administrator, not by this role selector.</p><button class="button-link" id="signup">Create a citizen account</button>`:`<div class="notice">Demo Mode uses sample incidents and explicit simulated detections. Changes last for this session. No AI or authentication service is connected.</div><button class="btn primary full" id="demo-enter">Enter ${state.loginRole||'citizen'} demo</button>`}<div class="divider">CITIZENS · AUTHORITIES · FIELD TEAMS</div><button class="btn full" id="connection-login">${icon('settings')}Connect Supabase & live AI</button></section></div>`}
function render(){maps.forEach(m=>m.remove());maps=[];if(!state.role&&!['home','login','login-citizen','login-authority','login-worker','settings'].includes(state.page)){state.loginRole='authority';state.page='login'}const allowed={citizen:['live-scan','citizen','report','reports','nearby','resolved','detail'],worker:['tasks','completed','detail'],authority:['live-scan','dashboard','incidents','map','analytics','workers','drivescan','assistant','detail']};if(state.role&&!['home','login','settings'].includes(state.page)&&!allowed[state.role].includes(state.page))state.page={citizen:'citizen',worker:'tasks',authority:'dashboard'}[state.role];let content=state.page==='home'?home():(state.page==='login'||state.page.startsWith('login-'))?login():shell(state.page==='dashboard'?dashboard():secondary());$('#app').innerHTML=content;bind();if(['home','dashboard','map','nearby','detail','report'].includes(state.page))initMaps();}
function secondary(){return '<div class="empty">Workspace is being prepared.</div>'}
function initMaps(){if(!window.L){document.querySelectorAll('.map').forEach(e=>e.innerHTML='<div class="map-error">Map unavailable. Coordinates remain available in incident details.</div>');return}document.querySelectorAll('.map').forEach(el=>{const m=L.map(el,{scrollWheelZoom:false,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([12.9735,77.642],14);maps.push(m);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(m);incidents.forEach(i=>{const p=i.status==='Resolved'?'resolved':priority(i).level.toLowerCase(),color={critical:'#d94f50',high:'#e39033',medium:'#d9b84d',low:'#2ba283',resolved:'#229d73'}[p];L.marker([i.latitude,i.longitude],{icon:L.divIcon({className:'',html:`<div class="marker" style="background:${color}"></div>`,iconSize:[18,18]})}).addTo(m).bindPopup(`<b>${esc(i.id)} · ${i.issue_type}</b><br>${esc(i.address)}<br>${priority(i).level} · ${esc(i.status)}<br>${i.reports} reports · ${esc(i.department)}<br><button class="button-link" onclick="openIncident('${esc(i.id)}')">View incident</button>`)});})}
function openIncident(id){state.selected=incidents.find(i=>i.id===id);if(state.selected){navigate('detail')}}
function legacyBind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>navigate(el.dataset.page));document.querySelectorAll('[data-incident]').forEach(el=>{el.onclick=()=>openIncident(el.dataset.incident);el.onkeydown=e=>{if(e.key==='Enter')el.click()}});document.querySelectorAll('[data-role]').forEach(el=>el.onclick=()=>{state.loginRole=el.dataset.role;render()});for(const id of ['citizen-login','hero-report'])if($('#'+id))$('#'+id).onclick=()=>{state.loginRole='citizen';navigate('login')};if($('#authority-login'))$('#authority-login').onclick=()=>{state.loginRole='authority';navigate('login')};if($('#explore'))$('#explore').onclick=()=>{if(state.live){state.loginRole='authority';navigate('login')}else{state.role='authority';navigate('dashboard')}};if($('#demo-enter'))$('#demo-enter').onclick=()=>{state.role=state.loginRole||'citizen';navigate({authority:'dashboard',worker:'tasks',citizen:'citizen'}[state.role])};for(const id of ['settings-home','connection-login'])if($('#'+id))$('#'+id).onclick=()=>navigate('settings');if($('#menu'))$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');if($('#signout'))$('#signout').onclick=async()=>{if(client)await client.auth.signOut();state.role=null;state.user=null;navigate('home')};document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{state.filter[el.dataset.filter]=el.value;render()});if($('#search'))$('#search').oninput=e=>{state.filter.search=e.target.value;const cursor=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor)};if($('#refresh'))$('#refresh').onclick=async()=>{await refresh();render();toast('Incident view refreshed')};bindSecondary();}
async function refresh(){if(!client)return;const {data,error}=await client.from('incident_view').select('*').order('created_at',{ascending:false});if(error){toast(error.message);return}incidents=data||[];}
function bindSecondary(){}

